 {#if menuOpen}<nav id="mobile-nav" class="mobile-nav" aria-label="Mobilní navigace">{#each [['/','Úvod'],['/#sluzby','Služby'],['/realizace.html','Realizace'],['/#pristup','Náš přístup'],['/kontakt.html','Kontakt']] as [url,label]}<a href={url} onclick={()=>menuOpen=false}>{label}<ArrowUpRight size={20}/></a>{/each}{@render quoteButton()}</nav>{/if}
</header>
<main id="obsah">
 {#if home}
